  function historyStudentKey(){
    var raw = '';
    try{ raw = String(window.prenomActuel || localStorage.getItem('hibou_prenom') || localStorage.getItem('hibou_last_prenom') || localStorage.getItem('elevePrenom') || 'eleve'); }catch(e){ raw = 'eleve'; }
    raw = raw.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');
    return raw || 'eleve';
  }
  function saveBilanResult(subject, payload){
    try{
      payload = payload || {};
      var key = 'hibou_bilans_' + historyStudentKey();
      var data = JSON.parse(localStorage.getItem(key) || '{}');
      data[subject] = payload;
      localStorage.setItem(key, JSON.stringify(data));

      /* V25.7.57 : connexion directe et fiable à « Mon parcours récent ».
         Le journal est alimenté sans dépendre uniquement de l'événement bilan-updated. */
      if(!payload.__hibouJournalLogged && typeof window.hibouTrackEvent === 'function' && payload.score != null && payload.total != null){
        var subjectLabel = String(payload.subject || subject || 'Bilan').trim();
        window.hibouTrackEvent({
          type: 'bilan_reussi',
          matiere: subjectLabel,
          domaine: 'Bilan',
          titre: 'Bilan ' + subjectLabel + ' terminé',
          detail: payload.score + '/' + payload.total,
          score: payload.score,
          total: payload.total,
          source: 'bilan_' + String(subject || subjectLabel).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'')
        });
        /* Empêche l'écouteur du journal d'enregistrer une seconde fois le même bilan. */
        payload.__hibouJournalLogged = true;
      }

      window.dispatchEvent(new CustomEvent('hibou:bilan-updated', {detail:{subject:subject,result:payload}}));
    }catch(e){
      try{ console.error('Erreur enregistrement bilan / parcours', e); }catch(ignore){}
    }
  }
  function renderHistoryAssessment(card, exo){
    card.classList.add('v24-history-assessment-card');
    var selected = {};
    var skills = exo.skills || [];
    var questions = exo.questions || [];
    var skillMap = {};
    var questionEls = [];
    skills.forEach(function(s){ skillMap[s.id] = s; });
    var skillBox = document.createElement('div');
    skillBox.className = 'v24-history-skills';
    skills.forEach(function(s){
      var d = document.createElement('div');
      d.className = 'v24-history-skill';
      d.innerHTML = esc(s.icon || '✓') + ' ' + esc(s.title || '') + '<small>' + esc(s.desc || '') + '</small>';
      skillBox.appendChild(d);
    });
    card.appendChild(skillBox);
    var list = document.createElement('div');
    list.className = 'v24-history-assessment-list';
    skills.forEach(function(skill, si){
      var group = document.createElement('section');
      group.className = 'v24-history-skill-group';
      group.innerHTML = '<h4>'+(si+1)+'. '+esc(skill.icon || '✓')+' '+esc(skill.title || '')+'<small>'+esc(skill.desc || '')+'</small></h4>';
      questions.forEach(function(q, qi){
        if(q.skill !== skill.id) return;
        var box = document.createElement('div');
        box.className = 'v24-history-question';
        box.innerHTML = '<b>Question '+(qi+1)+'</b><p>'+esc(q.q)+'</p>';
        var opts = document.createElement('div');
        opts.className = 'v24-history-options';
        q.options.forEach(function(opt, oi){
          var btn = document.createElement('button');
          btn.type = 'button';
          btn.className = 'v24-history-option';
          btn.textContent = opt;
          btn.addEventListener('click', function(ev){
            ev.preventDefault();
            selected[qi] = oi;
            Array.prototype.forEach.call(opts.children, function(b){ b.classList.remove('selected'); });
            btn.classList.add('selected');
          }, true);
          opts.appendChild(btn);
        });
        box.appendChild(opts);
        questionEls[qi] = box;
        group.appendChild(box);
      });
      list.appendChild(group);
    });
    card.appendChild(list);
    var resultBtn = document.createElement('button');
    resultBtn.type = 'button';
    resultBtn.className = 'v24-history-result-btn';
    resultBtn.textContent = 'Voir mon bilan';
    var result = document.createElement('div');
    result.className = 'v24-history-final-message';
    result.style.display = 'none';
    resultBtn.addEventListener('click', function(ev){
      ev.preventDefault();
      if(Object.keys(selected).length < questions.length){
        result.style.display = 'block';
        result.innerHTML = 'Il reste ' + (questions.length - Object.keys(selected).length) + ' réponse(s) à choisir avant le bilan.';
        return;
      }
      var scores = {};
      skills.forEach(function(s){ scores[s.id] = {ok:0,total:0,skill:s}; });
      questions.forEach(function(q, qi){
        if(!scores[q.skill]) scores[q.skill] = {ok:0,total:0,skill:{id:q.skill,title:q.skill,icon:'✓'}};
        scores[q.skill].total++;
        if(selected[qi] === q.correct) scores[q.skill].ok++;
        var qBox = questionEls[qi];
        Array.prototype.forEach.call(qBox.querySelectorAll('.v24-history-option'), function(b, oi){
          b.disabled = true;
          b.classList.toggle('correct', oi === q.correct);
          b.classList.toggle('wrong', oi === selected[qi] && oi !== q.correct);
        });
      });
      var totalOk = questions.reduce(function(sum,q,qi){ return sum + (selected[qi] === q.correct ? 1 : 0); }, 0);
      var redCount = 0;
      var html = '<div class="v24-history-results">';
      Object.keys(scores).forEach(function(id){
        var s = scores[id];
        var color = s.ok === 3 ? 'green' : (s.ok === 2 ? 'orange' : 'red');
        if(color === 'red') redCount++;
        var label = color === 'green' ? 'Acquis' : (color === 'orange' ? 'Presque acquis' : 'À retravailler');
        html += '<div class="v24-history-result '+color+'">'+esc(s.skill.icon || '✓')+' '+esc(s.skill.title || id)+'<small>'+s.ok+' / '+s.total+' - '+label+'</small></div>';
      });
      html += '</div>';
      var validated = redCount === 0;
      html += '<div class="v24-history-final-message">'+(validated ? 'Bravo, bilan Histoire validé : aucune compétence en rouge.' : 'Bilan terminé : regarde les compétences rouges à retravailler.')+' Score : '+totalOk+' / '+questions.length+'.</div>';
      result.style.display = 'block';
      result.innerHTML = html;
      saveBilanResult('histoire', {subject:'Histoire', icon:'🏛️', score:totalOk, total:questions.length, validated:validated, date:new Date().toISOString(), skills:Object.keys(scores).map(function(id){var s=scores[id];return {id:id,title:s.skill.title,ok:s.ok,total:s.total,color:s.ok===3?'green':(s.ok===2?'orange':'red')};})});
    }, true);
    card.appendChild(resultBtn);
    card.appendChild(result);
  }

