    grid.querySelector('#v24HistoryBack').addEventListener('click', function(ev){ev.preventDefault();ev.stopPropagation();renderHistoryHome(grid);}, true);

    /* NAV-01 Histoire : accès aux leçons en superposition, sans reconstruire les exercices. */
